from solution import sum_gp


def test_issue_example():
    """Example from issue: sum_gp(1,5,2)==31."""
    assert sum_gp(1, 5, 2) == 31  # 1+2+4+8+16=31


def test_issue_ratio_one():
    """Sum of geometric progression series with ratio 1 is a*n."""
    assert sum_gp(3, 4, 1) == 12  # 3+3+3+3=12


def test_issue_single_term():
    """Sum of geometric progression series with one term is a."""
    assert sum_gp(7, 1, 9) == 7  # 7=7


def test_issue_zero_terms():
    """Sum of geometric progression series with zero terms is 0."""
    assert sum_gp(5, 0, 2) == 0  # empty sum=0


def test_issue_zero_first_term():
    """Sum of geometric progression series starting at 0 is 0."""
    assert sum_gp(0, 4, 3) == 0  # 0+0+0+0=0


def test_issue_zero_ratio():
    """Sum of geometric progression series with ratio 0 is a."""
    assert sum_gp(4, 3, 0) == 4  # 4+0+0=4


def test_issue_negative_ratio():
    """Sum of geometric progression series with negative ratio alternates."""
    assert sum_gp(1, 4, -2) == -5  # 1-2+4-8=-5


def test_issue_common_ratio_three():
    """Sum of geometric progression series for a=2, n=4, r=3."""
    assert sum_gp(2, 4, 3) == 80  # 2+6+18+54=80


def test_issue_negative_first_term():
    """Sum of geometric progression series starting with negative a."""
    assert sum_gp(-2, 3, 2) == -14  # -2-4-8=-14


def test_issue_half_ratio():
    """Sum of geometric progression series with fractional ratio."""
    assert sum_gp(8, 3, 0.5) == 14  # 8+4+2=14


def test_contract_ten_powers_of_two():
    """Sum of geometric progression series follows 1+2+...+512."""
    assert sum_gp(1, 10, 2) == 1023  # 1+2+4+8+16+32+64+128+256+512=1023


def test_contract_two_terms():
    """Sum of geometric progression series with two terms is a+a*r."""
    assert sum_gp(5, 2, 3) == 20  # 5+15=20
